{"command": "mkdir -p /tmp/build && cd /tmp/build && cat > go.mod <<'EOF'
module tparse

go 1.21
EOF
cat > main.go <<'GOEOF'
package main

import (
	"bufio"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"sort"
	"strings"
	"syscall"
	"time"
	"unsafe"
)

const usageText = `Usage:
    go test ./... -json | tparse [options...]
    go test [packages...] -json | tparse [options...]
    go test [packages...] -json > pkgs.out ; tparse [options...] -file pkgs.out

Options:
    -h                 Show help.
    -v                 Show version.
    -all               Display table event for pass and skip. (Failed items always displayed)
    -pass              Display table for passed tests.
    -skip              Display table for skipped tests.
    -notests           Display packages containing no test files or empty test files.
    -smallscreen       Split subtest names vertically to fit on smaller screens.
    -slow              Number of slowest tests to display. Default is 0, display all.
    -sort              Sort table output by attribute [name, elapsed, cover]. Default is name.
    -nocolor           Disable all colors. (NO_COLOR also supported)
    -format            The output format for tables [basic, plain, markdown]. Default is basic.
    -file              Read test output from a file.
    -follow            Follow raw output from go test to stdout.
    -follow-output     Write raw output from go test to a file (takes precedence over -follow).
    -include-timestamp Include timestamps in follow output.
    -progress          Print a single summary line for each package. Useful for long running test suites.
    -compare           Compare against a previous test output file. (experimental)
    -trimpath          Remove path prefix from package names in output, simplifying their display.
`

type rfcTime struct{ time.Time }

func (t *rfcTime) UnmarshalJSON(b []byte) error {
	if string(b) == "null" {
		return nil
	}
	if len(b) < 2 || b[0] != '"' || b[len(b)-1] != '"' {
		return errors.New("Time.UnmarshalJSON: input is not a JSON string")
	}
	s := string(b[1 : len(b)-1])
	tt, err := time.Parse(time.RFC3339, s)
	if err != nil {
		return err
	}
	t.Time = tt
	return nil
}

type event struct {
	Time    rfcTime
	Action  string
	Package string
	Test    string
	Elapsed float64
	Output  string
}

type testNode struct {
	name     string
	status   string
	elapsed  float64
	output   []string
	children []*testNode
	parent   *testNode
}

func (t *testNode) lines() []*testNode {
	var out []*testNode
	out = append(out, t)
	for _, c := range t.children {
		out = append(out, c.lines()...)
	}
	return out
}

type pkgResult struct {
	key      string
	name     string
	status   string
	elapsed  float64
	cover    string
	cached   bool
	pass     int
	fail     int
	skip     int
	tests    []*testNode
	testMap  map[string]*testNode
	output   []string
	panicAt  int
	panicOff int
	hasPanic bool
}

type notestEntry struct {
	name   string
	marker string
}

type summary struct {
	pkgs    map[string]*pkgResult
	order   []string
	notests []*notestEntry
	failed  bool
}

func newPkg(key string) *pkgResult {
	return &pkgResult{key: key, testMap: map[string]*testNode{}, panicAt: -1}
}

func (p *pkgResult) node(name string) *testNode {
	if n, ok := p.testMap[name]; ok {
		return n
	}
	n := &testNode{name: name}
	p.testMap[name] = n
	// attach to parent if it exists
	if i := strings.LastIndex(name, "/"); i > 0 {
		if par, ok := p.testMap[name[:i]]; ok {
			n.parent = par
			par.children = append(par.children, n)
			return n
		}
	}
	p.tests = append(p.tests, n)
	return n
}

func main() {
	opts := options{}
	fs := newFlagSet(&opts)
	fs.Parse(os.Args[1:])

	if opts.help {
		fmt.Print(usageText)
		return
	}
	if opts.version {
		fmt.Println("tparse version: (devel)")
		return
	}
	if !validFormat(opts.format) {
		fmt.Fprintf(os.Stderr, "invalid option:%q. The -format flag must be one of: basic, plain or markdown\n", opts.format)
		return
	}
	if !validSort(opts.sortKey) {
		fmt.Fprintf(os.Stderr, "invalid option:%q. The -sort flag must be one of: name, elapsed or cover\n", opts.sortKey)
		return
	}
	opts.color = !opts.nocolor
