		if !p.hasPanic && strings.HasPrefix(e.Output, "panic: ") {
			p.hasPanic = true
			p.panicIdx = len(p.allOutput)
			if e.Test != "" {
				p.panicTest = e.Test
			}
			p.panicOff = len(p.allOutputRaw)
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("received scanning error: %v", err)
	}
	if len(s.order) == 0 {
		return nil, nil
	}
	return s, nil
}
