	name     string
	status   string
	elapsed  float64
	output   []string
	children []*testNode
	parent   *testNode
}

func (t *testNode) flat() []*testNode {
	out := []*testNode{t}
	for _, c := range t.children {
		out = append(out, c.flat()...)
	}
	return out
}

func (t *testNode) root() *testNode {
	n := t
	for n.parent != nil {
		n = n.parent
	}
	return n
}

type pkgResult struct {
	key        string
	name       string
	status     string
	elapsed    float64
	cover      string
	cached     bool
	pass       int
	fail       int
	skip       int
	tests      []*testNode
	testMap    map[string]*testNode
	output     []string
	allOutput  []outLine
	hasPanic   bool
	panicIdx   int
	panicTest  string
}

type notestEntry struct {
	name   string
	marker string
}

type summary struct {
	pkgs    map[string]*pkgResult
	order   []string
	notests []*notestEntry
	failed  bool
}

func newPkg(key string) *pkgResult {
	return &pkgResult{key: key, testMap: map[string]*testNode{}, panicIdx: -1}
}

func (p *pkgResult) node(name string) *testNode {
	if n, ok := p.testMap[name]; ok {
		return n
	}
	n := &testNode{name: name}
	p.testMap[name] = n
	if i := strings.LastIndex(name, "/"); i > 0 {
		if par, ok := p.testMap[name[:i]]; ok {
			n.parent = par
			par.children = append(par.children, n)
			return n
		}
	}
	p.tests = append(p.tests, n)
	return n
}

var coverRe = regexp.MustCompile(`coverage:\s*(\d+\.\d)%.*of statements`)

func parsePkgOutput(s *summary, p *pkgResult, line string) {
	if m := coverRe.FindStringSubmatch(line); m != nil {
		p.cover = m[1] + "%"
	}
	if strings.HasPrefix(line, "ok  \t") && strings.Contains(line, "(cached)") {
		p.cached = true
	}
	if strings.HasPrefix(line, "?   \t") {
		fields := strings.Split(line, "\t")
		if len(fields) >= 3 && strings.TrimSpace(fields[2]) == "[no test files]" {
			delete(s.pkgs, p.key)
			for i, k := range s.order {
				if k == p.key {
					s.order = append(s.order[:i], s.order[i+1:]...)
					break
				}
			}
			s.notests = append(s.notests, &notestEntry{name: strings.TrimSpace(fields[1]), marker: "[no test files]"})
		}
	}
}
