{"command": "cd /tmp/build && cat > render.go <<'GOEOF'
package main

import (
	"fmt"
	"io"
	"sort"
	"strings"
)

// ---------- helpers ----------

const (
	alignCenter = 0
	alignLeft   = 1
)

type cell struct {
	lines []string
}

func maxLen(c cell) int {
	m := 0
	for _, l := range c.lines {
		if len(l) > m {
			m = len(l)
		}
	}
	return m
}

func padCenter(s string, w int) string {
	if len(s) >= w {
		return s
	}
	extra := w - len(s)
	left := extra / 2
	right := extra - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

func padLeft(s string, w int) string {
	if len(s) >= w {
		return s
	}
	return " " + s + strings.Repeat(" ", w-1-len(s))
}

func padCell(s string, w int, align int) string {
	if align == alignLeft {
		return padLeft(s, w)
	}
	return padCenter(s, w)
}

// ---------- colors ----------

func colorize(o *options, code, s string) string {
	if !o.color {
		return s
	}
	return "\x1b[" + code + "m" + s + "\x1b[0m"
}

func statusColor(status string) string {
	switch status {
	case "PASS":
		return "92"
	case "FAIL", "PANIC":
		return "91"
	case "SKIP", "NOTEST":
		return "93"
	}
	return "0"
}

func statusEmoji(status string) string {
	switch status {
	case "PASS":
		return "🟢"
	case "FAIL", "PANIC":
		return "🔴"
	case "SKIP", "NOTEST":
		return "🟡"
	}
	return ""
}

func displayStatus(o *options, status string) string {
	if o.format == "markdown" {
		if o.color {
			return statusEmoji(status) + " " + status
		}
		return status
	}
	return colorize(o, statusColor(status), status)
}

// ---------- box ----------

func boxLines(status, name, test string) []string {
	text := status + "  package: " + name
	if test != "" {
		text += " • " + test
	}
	w := len(text) + 6
	line := "   " + text + "   "
	return []string{
		"┏" + strings.Repeat("━", w-2) + "┓",
		"┃" + line + "┃",
		"┗" + strings.Repeat("━", w-2) + "┛",
	}
}

func colorBoxLines(o *options, status, name, test string) []string {
	lines := boxLines(status, name, test)
	if !o.color {
		return lines
	}
	c := colorize(o, "38;5;103", "")
	// rebuild middle line with colored status
	text := colorize(o, "91", colorize(o, "91", status)) + "  package: " + name
	if test != "" {
		text += " • " + test
	}
	w := len(status) + len("  package: ") + len(name) + 6
	if test != "" {
		w += len(" • ") + len(test)
	}
	lines[0] = colorize(o, "38;5;103", "┏"+strings.Repeat("━", w-2)+"┓")
	lines[1] = colorize(o, "38;5;103", "┃") + "   " + text + "   " + colorize(o, "38;5;103", "┃")
	lines[2] = colorize(o, "38;5;103", "┗"+strings.Repeat("━", w-2)+"┛")
	_ = c
	return lines
}

// ---------- wrap ----------

func wrapLine(s string, width int) []string {
	if width <= 0 {
		return []string{s}
	}
	var out []string
	for len(s) > width {
		lim := width + 1
		if lim > len(s) {
			lim = len(s)
		}
		i := strings.LastIndex(s[:lim], " ")
		if i <= 0 {
			i = width
		}
		out = append(out, s[:i])
		s = strings.TrimLeft(s[i:], " ")
	}
	out = append(out, s)
	return out
}

// ---------- table ----------

type table struct {
	headers []cell
	rows    [][]cell
	aligns  []int
}

func (t *table) widths() []int {
	n := len(t.headers)
	w := make([]int, n)
	for i, c := range t.headers {
		if l := maxLen(c) + 2; l > w[i] {
			w[i] = l
		}
	}
	for _, r := range t.rows {
		for i, c := range r {
			if l := maxLen(c) + 2; l > w[i] {
				w[i] = l
			}
		}
	}
	return w
}

func (t *table) rowHeight(r []cell) int {
	h := 1
	for _, c := range r {
		if len(c.lines) > h {
			h = len(c.lines)
		}
	}
	return h
}

func (t *table) printBasic(o *options, out io.Writer) {
	ws := t.widths()
	border := func(left, mid, right, fill string) {
		var b strings.Builder
		b.WriteString(left)
		for i, wd := range ws {
			if i > 0 {
				b.WriteString(mid)
			}
			b.WriteString(strings.Repeat(fill, wd))
		}
		b.WriteString(right)
		fmt.Fprintln(out, b.String())
	}
	border("╭", "┬", "╮", "─")
	t.printRowLine(o, out, t.headers, ws, "│")
	border("├", "┼", "┤", "─")
	for _, r := range t.rows {
		t.printRowLine(o, out, r, ws, "│")
	}
	border("╰", "┴", "╯", "─")
}

func (t *table) printRowLine(o *options, out io.Writer, r []cell, ws []int, sep string) {
	h := 1
	for _, c := range r {
		if len(c.lines) > h {
			h = len(c.lines)
		}
	}
	for li := 0; li < h; li++ {
		var b strings.Builder
		b.WriteString(sep)
		for i, c := range r {
			s := ""
			if li < len(c.lines) {
				s = c.lines[li]
			}
			b.WriteString(padCell(s, ws[i], t.aligns[i]))
			b.WriteString(sep)
		}
		fmt.Fprintln(out, b.String())
	}
}

func (t *table) printPlain(o *options, out io.Writer) {
	ws := t.widths()
	total := 1
	for _, wd := range ws {
		total += wd + 1
	}
	blank := strings.Repeat(" ", total)
	fmt.Fprintln(out, blank)
	t.printPlainRow(o, out, t.headers, ws)
	fmt.Fprintln(out, blank)
