		for _, l := range lines {
			fmt.Fprintln(out, colorize(o, "31", l))
		}
		fmt.Fprintln(out, "```")
		return
	}
	for _, l := range lines {
		fmt.Fprintln(out, colorize(o, "31", l))
	}
}

func pkgStatusText(p *pkgResult) string {
	if p.hasPanic {
