		boxW := len("PANIC  package: "+p.name) + 6
		if p.panicTest != "" {
			boxW += len(" • ") + len(p.panicTest)
		}
		bw := o.width
		if boxW > bw {
			bw = boxW
		}
		fmt.Fprintln(out, padStr(hdr, bw))
		printPanicLines(o, out, p, bw)
		return
	}
	box := colorBoxLines(o, "PANIC", displayName(o, p.name), p.panicTest)
	bw := o.width
	if l := len([]rune(stripANSI(box[0]))); l > bw {
