	printPkgTable(s, o, rows, os.Stdout)
}

func printMarkdownFailSections(s *summary, o *options, rows []pkgRow, out io.Writer) {
	for _, r := range rows {
		p := r.p
		if p.hasPanic {
			printPanicBlock(o, out, p)
			continue
		}
		gs := groupsFor(p)
		if len(gs) == 0 {
			continue
		}
		hdr := "## " + displayStatus(o, pkgStatusText(p)) + " • " + displayName(o, p.name)
		fmt.Fprintln(out, hdr)
		fmt.Fprintln(out, "")
		for _, g := range gs {
