	"os"
	"strings"
	"time"
)

var followPrefixes = []string{"=== RUN ", "=== CONT ", "=== PAUSE ", "--- PASS ", "--- SKIP "}

func followAllowed(e event, line string) bool {
	if e.Test == "" {
		t := strings.TrimSpace(line)
		if t == "PASS" || t == "FAIL" {
			return false
		}
	}
	for _, p := range followPrefixes {
		if strings.HasPrefix(line, p) {
			return false
		}
	}
	return true
}

func scan(input io.Reader, o *options, followW *os.File) (*summary, error) {
	s := &summary{pkgs: map[string]*pkgResult{}}
	var follow io.Writer
	if o.followOutput != "" {
		follow = followW
	} else if o.follow {
		follow = os.Stdout
	}

	scanner := bufio.NewScanner(input)
	scanner.Buffer(make([]byte, 0, 64*1024), 16*1024*1024)
	for scanner.Scan() {
		line := scanner.Bytes()
		var e event
		if err := json.Unmarshal(line, &e); err != nil {
			if _, ok := err.(*time.ParseError); ok {
				return nil, err
			}
			if len(s.order) == 0 {
				if follow != nil {
					fmt.Fprintln(follow, string(line))
				}
				continue
			}
			if o.follow && o.followOutput == "" {
				fmt.Println()
			}
			return nil, nil
		}
		p := s.pkgs[e.Package]
		if p == nil {
			p = newPkg(e.Package)
			s.pkgs[e.Package] = p
			s.order = append(s.order, e.Package)
		}
		switch e.Action {
		case "pass":
			if e.Test == "" {
				p.name = e.Package
				if p.status != "notest" {
					p.status = "pass"
				}
				p.elapsed = e.Elapsed
				if o.progress {
					printProgress(o, "PASS", e.Elapsed, e.Package)
				}
			} else {
				n := p.node(e.Test)
				n.status = "pass"
				n.elapsed = e.Elapsed
			}
		case "fail":
			if e.Test == "" {
				p.name = e.Package
				if p.status != "notest" {
					p.status = "fail"
				}
				p.elapsed = e.Elapsed
				s.failed = true
				if o.progress {
					printProgress(o, "FAIL", e.Elapsed, e.Package)
				}
			} else {
				n := p.node(e.Test)
				n.status = "fail"
				n.elapsed = e.Elapsed
			}
		case "skip":
			if e.Test == "" {
				if !p.notest {
					p.name = ""
					p.status = ""
					p.elapsed = 0
				}
			} else {
				n := p.node(e.Test)
				n.status = "skip"
				n.elapsed = e.Elapsed
			}
		case "output":
			if e.Test != "" {
				n := p.node(e.Test)
				n.output = append(n.output, e.Output)
			} else {
				parsePkgOutput(p, e.Output)
			}
			p.allOutput = append(p.allOutput, outLine{test: e.Test, line: e.Output})
			if !p.hasPanic && strings.HasPrefix(e.Output, "panic: ") {
				p.hasPanic = true
				p.panicIdx = len(p.allOutput) - 1
				p.panicTest = e.Test
				s.failed = true
			}
		default:
			if e.Test == "" {
				p.pkgFail++
			} else {
				p.node(e.Test)
			}
		}
		if follow != nil {
			trimmed := strings.TrimSuffix(e.Output, "\n")
			if followAllowed(e, trimmed) {
				if o.includeTimestamp {
					fmt.Fprintf(follow, "%s %s\n", e.Time.Time.Format(time.RFC3339), trimmed)
				} else {
					fmt.Fprintln(follow, trimmed)
				}
			}
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("received scanning error: %v", err)
	}
	if len(s.order) == 0 {
		return nil, nil
	}
	return s, nil
}
