{"command": "cd /tmp/build && sed -i 's/r >= 0x1F300 \&\& r <= 0x1F64F,/r >= 0x1F300 \&\& r <= 0x1FAFF,/' width.go && cat > summary.go <<'GOEOF'
package main

import (
	"fmt"
	"io"
	"os"
	"sort"
	"strings"
)

type pkgRow struct {
	p      *pkgResult
	notest bool
}

// failOrder returns packages sorted by name (used for detail output ordering).
func failOrder(s *summary) []*pkgResult {
	var list []*pkgResult
	for _, k := range s.order {
		if p, ok := s.pkgs[k]; ok {
			list = append(list, p)
		}
	}
	sort.SliceStable(list, func(i, j int) bool { return list[i].name < list[j].name })
	return list
}

func buildRows(s *summary, o *options) []pkgRow {
	var panicRows, regularRows, notestRows []pkgRow
	for _, key := range s.order {
		p, ok := s.pkgs[key]
		if !ok {
			continue
		}
		if p.notest {
			notestRows = append(notestRows, pkgRow{p: p, notest: true})
		} else if p.hasPanic {
			panicRows = append(panicRows, pkgRow{p: p})
		} else {
			regularRows = append(regularRows, pkgRow{p: p})
		}
	}
	sort.SliceStable(panicRows, func(i, j int) bool { return panicRows[i].p.name < panicRows[j].p.name })
	sort.SliceStable(regularRows, func(i, j int) bool { return regularRows[i].p.name < regularRows[j].p.name })
	sort.SliceStable(notestRows, func(i, j int) bool { return notestRows[i].p.name < notestRows[j].p.name })
	rows := append(append(panicRows, regularRows...), notestRows...)
	if !o.notests && len(rows) > 1 {
		var out []pkgRow
		for _, r := range rows {
			if !r.notest {
				out = append(out, r)
			}
		}
		rows = out
	}
	return rows
}

func displayName(o *options, name string) string {
	if o.trimpath != "" {
		return strings.TrimPrefix(name, o.trimpath)
	}
	return name
}

func printProgress(o *options, status string, elapsed float64, pkg string) {
	st := colorize(o, statusColor(status), status)
	fmt.Fprintf(os.Stdout, "[%s]\t%10s\t%s\n", st, fmt.Sprintf("%.2fs", elapsed), displayName(o, pkg))
}

func separator(o *options, out io.Writer) {
	fmt.Fprintln(out, strings.Repeat("─", o.width))
	fmt.Fprintln(out, colorize(o, "2", "")+strings.Repeat(" ", o.width))
}

type group struct {
	name     string
	rootName string
	headers  []string
	outputs  []string
}

func failDetailHeaderPrefix(l string) bool {
	return strings.HasPrefix(l, "--- FAIL:")
}

func dropPrefix(l string) bool {
	for _, p := range []string{"=== RUN   ", "=== CONT  ", "=== PAUSE "} {
		if strings.HasPrefix(l, p) {
			return true
		}
	}
	return false
}

func groupsFor(p *pkgResult) []group {
	var gs []group
	for _, n := range p.testOrder {
		if n.status == "pass" || n.status == "skip" {
			continue
		}
		g := group{name: n.name, rootName: p.rootName(n.name)}
		for _, l := range n.output {
			if failDetailHeaderPrefix(l) {
				g.headers = append(g.headers, strings.TrimSuffix(l, "\n"))
			} else if !dropPrefix(l) {
				g.outputs = append(g.outputs, l)
			}
		}
		gs = append(gs, g)
	}
	sort.SliceStable(gs, func(i, j int) bool { return gs[i].name < gs[j].name })
	return gs
}

func printGroupLines(o *options, out io.Writer, g group) {
	col := o.format != "markdown"
	for _, h := range g.headers {
		if col {
			fmt.Fprint(out, colorize(o, "31", h))
		} else {
			fmt.Fprint(out, h)
		}
	}
	fmt.Fprintln(out, "")
	if len(g.outputs) > 0 {
		fmt.Fprintln(out, "")
		for _, l := range g.outputs {
			fmt.Fprint(out, l)
		}
		fmt.Fprintln(out, "")
	}
}

func pkgStatusText(p *pkgResult) string {
	if p.hasPanic {
		return "PANIC"
	}
	return strings.ToUpper(p.status)
}

func printFailDetails(s *summary, o *options, out io.Writer) {
	prevRoot := ""
	for _, p := range failOrder(s) {
		if p.notest {
			continue
		}
		if p.hasPanic {
			printPanicBlock(o, out, p)
			continue
		}
		gs := groupsFor(p)
		if len(gs) == 0 {
			continue
		}
		for _, l := range colorBoxLines(o, pkgStatusText(p), displayName(o, p.name), "") {
			fmt.Fprintln(out, l)
		}
		fmt.Fprintln(out, "")
		for i, g := range gs {
			if i > 0 && g.rootName != prevRoot {
				separator(o, out)
			}
			prevRoot = g.rootName
			printGroupLines(o, out, g)
		}
	}
}

func panicBlockWidth(o *options, hdr string) int {
	bw := o.width
	if w := visibleWidth(hdr); w > bw {
		bw = w
	}
	return bw
}

func printPanicBlock(o *options, out io.Writer, p *pkgResult) {
	if o.format == "markdown" {
		hdr := "## " + displayStatus(o, "PANIC") + " • " + displayName(o, p.name)
		if p.panicTest != "" {
			hdr += " • " + p.panicTest
		}
		bw := panicBlockWidth(o, hdr)
		fmt.Fprintln(out, padStr(hdr, bw))
		printPanicLines(o, out, p, bw)
		return
	}
	box := colorBoxLines(o, "PANIC", displayName(o, p.name), p.panicTest)
	bw := o.width
	if l := visibleWidth(box[0]); l > bw {
		bw = l
	}
	for _, l := range box {
		fmt.Fprintln(out, padStr(l, bw))
	}
	printPanicLines(o, out, p, bw)
}

func printPanicLines(o *options, out io.Writer, p *pkgResult, bw int) {
	var sb strings.Builder
	for _, ol := range p.allOutput[p.panicIdx:] {
		sb.WriteString(strings.ReplaceAll(ol.line, "\t", "    "))
	}
	text := sb.String()
	for _, line := range strings.Split(text, "\n") {
		line = strings.TrimRight(line, " \t")
		for _, w := range wrapLine(line, o.width) {
			fmt.Fprintln(out, padStr(w, bw))
		}
	}
}

func padStr(s string, w int) string {
	vw := visibleWidth(s)
	if vw >= w {
		return s
	}
	return s + strings.Repeat(" ", w-vw)
}

// ---------- tests ----------

type testRow struct {
	name    string
	status  string
	elapsed float64
}

func testCellName(o *options, name string) cell {
	if o.smallscreen {
		return cell{lines: splitSmallName(name)}
	}
	return cell{lines: []string{name}}
}

func splitSmallName(name string) []string {
	if len(name) <= 32 || !strings.Contains(name, "/") {
		return []string{name}
	}
	parts := strings.Split(name, "/")
	lines := []string{parts[0]}
	for _, p := range parts[1:] {
		if len(p) <= 32 {
			lines = append(lines, " /"+p)
			continue
		}
		i := 0
		first := true
		for len(p[i:]) > 32 {
			prefix := " /"
			if !first {
				prefix = "  "
			}
			lines = append(lines, prefix+p[i:i+30]+" …")
			first = false
			i += 30
		}
		prefix := " /"
		if !first {
			prefix = "  "
		}
		lines = append(lines, prefix+p[i:])
	}
	return lines
}

func collectRows(p *pkgResult) (passRows, skipRows, failRows []testRow) {
	for _, n := range p.testOrder {
		tr := testRow{name: n.name, status: strings.ToUpper(n.status), elapsed: n.elapsed}
		switch n.status {
		case "pass":
			passRows = append(passRows, tr)
		case "skip":
			skipRows = append(skipRows, tr)
		default:
			failRows = append(failRows, tr)
		}
	}
	sort.SliceStable(passRows, func(i, j int) bool { return passRows[i].elapsed > passRows[j].elapsed })
	sort.SliceStable(skipRows, func(i, j int) bool { return skipRows[i].elapsed > skipRows[j].elapsed })
	sort.SliceStable(failRows, func(i, j int) bool { return failRows[i].elapsed > failRows[j].elapsed })
	return
}

func limitRows(rows []testRow, n int) []testRow {
	if n > 0 && len(rows) > n {
		return rows[:n]
	}
	return rows
}

func mergedRows(p *pkgResult, o *options) []testRow {
	passRows, skipRows, failRows := collectRows(p)
	passRows = limitRows(passRows, o.slow)
	skipRows = limitRows(skipRows, o.slow)
	failRows = limitRows(failRows, o.slow)
	var all []testRow
	all = append(all, passRows...)
	all = append(all, skipRows...)
	all = append(all, failRows...)
	return all
}

func showStatus(o *options, status string) bool {
	switch status {
	case "PASS":
		return o.all || o.pass
	case "SKIP":
		return o.all || o.skip
	}
	return true
}

func testTable(s *summary, o *options) *table {
	aligns := []int{alignCenter, alignCenter, alignLeft, alignLeft}
	headers := []cell{{lines: []string{"Status"}}, {lines: []string{"Elapsed"}}, {lines: []string{"Test"}}, {lines: []string{"Package"}}}
	if o.format == "markdown" {
		headers = headers[:3]
		aligns = aligns[:3]
	}
	t := &table{headers: headers, aligns: aligns}
	first := true
	for _, p := range failOrder(s) {
		if p.notest || p.hasPanic {
			continue
		}
		var shown []testRow
		for _, tr := range mergedRows(p, o) {
			if showStatus(o, tr.status) {
				shown = append(shown, tr)
			}
		}
		if len(shown) == 0 {
			continue
		}
		if !first && o.format != "markdown" {
			blank := make([]cell, len(headers))
			for i := range blank {
				blank[i] = cell{lines: []string{""}}
			}
			t.rows = append(t.rows, blank)
		}
		first = false
		for _, tr := range shown {
			cells := []cell{
				{lines: []string{displayStatus(o, tr.status)}},
				{lines: []string{fmt.Sprintf("%.2f", tr.elapsed)}},
				testCellName(o, tr.name),
			}
			if o.format != "markdown" {
				cells = append(cells, cell{lines: []string{displayName(o, p.name)}})
			}
			t.rows = append(t.rows, cells)
		}
	}
	if len(t.rows) == 0 {
		return nil
	}
	return t
}

// ---------- pkg table ----------

func pkgTable(s *summary, o *options, rows []pkgRow) *table {
	aligns := []int{alignCenter, alignCenter, alignLeft, alignCenter, alignCenter, alignCenter, alignCenter}
	headers := []cell{
		{lines: []string{"Status"}}, {lines: []string{"Elapsed"}}, {lines: []string{"Package"}},
		{lines: []string{"Cover"}}, {lines: []string{"Pass"}}, {lines: []string{"Fail"}}, {lines: []string{"Skip"}},
	}
	t := &table{headers: headers, aligns: aligns}
	for _, r := range rows {
		p := r.p
		st := pkgStatusText(p)
		elapsed := fmt.Sprintf("%.2fs", p.elapsed)
		if p.cached {
			elapsed = "(cached)"
		}
		cover := p.cover
		if cover == "" {
			cover = "--"
		}
		var pkgCell cell
		pass, fail, skip := "--", "--", "--"
		if r.notest {
			st = "NOTEST"
			pkgCell = cell{lines: []string{displayName(o, p.name), p.marker}}
		} else {
			pkgCell = cell{lines: []string{displayName(o, p.name)}}
			a, b, c := p.counts()
			pass, fail, skip = fmt.Sprintf("%d", a), fmt.Sprintf("%d", b), fmt.Sprintf("%d", c)
		}
		t.rows = append(t.rows, []cell{
			{lines: []string{displayStatus(o, st)}},
			{lines: []string{elapsed}},
			pkgCell,
			{lines: []string{cover}},
			{lines: []string{pass}},
			{lines: []string{fail}},
			{lines: []string{skip}},
		})
	}
	return t
}

// ---------- markdown ----------

func printMarkdownPkgSections(s *summary, o *options, out io.Writer) {
	if !(o.all || o.pass || o.skip) {
		return
	}
	for _, p := range failOrder(s) {
		if p.notest || p.hasPanic {
			continue
		}
		var shown []testRow
		for _, tr := range mergedRows(p, o) {
			if showStatus(o, tr.status) {
				shown = append(shown, tr)
			}
		}
		if len(shown) == 0 {
			continue
		}
		pass, fail, skip := p.counts()
		fmt.Fprintf(out, "## 📦 Package **`%s`**\n", displayName(o, p.name))
		fmt.Fprintln(out, "")
		fmt.Fprintf(out, "Tests: ✓ %d passed | %d skipped | %d failed\n", pass, skip, fail)
		fmt.Fprintln(out, "")
		fmt.Fprintln(out, "<details>")
		fmt.Fprintln(out, "")
		fmt.Fprintln(out, "<summary>Click for test summary</summary>")
		fmt.Fprintln(out, "")
		aligns := []int{alignCenter, alignCenter, alignLeft}
		headers := []cell{{lines: []string{"Status"}}, {lines: []string{"Elapsed"}}, {lines: []string{"Test"}}}
		t := &table{headers: headers, aligns: aligns}
		for _, tr := range shown {
			t.rows = append(t.rows, []cell{
				{lines: []string{displayStatus(o, tr.status)}},
				{lines: []string{fmt.Sprintf("%.2f", tr.elapsed)}},
				testCellName(o, tr.name),
			})
		}
		t.printMarkdown(o, out)
		fmt.Fprintln(out, "</details>")
		fmt.Fprintln(out, "")
		fmt.Fprintln(out, "")
	}
}

func printMarkdownFailSections(s *summary, o *options, out io.Writer) {
	for _, p := range failOrder(s) {
		if p.notest {
			continue
		}
		if p.hasPanic {
			printPanicBlock(o, out, p)
			continue
		}
		gs := groupsFor(p)
		if len(gs) == 0 {
			continue
		}
		fmt.Fprintln(out, "## "+displayStatus(o, pkgStatusText(p))+" • "+displayName(o, p.name))
		fmt.Fprintln(out, "")
		fmt.Fprintln(out, "```")
		prevRoot := ""
		for i, g := range gs {
			if i > 0 && g.rootName != prevRoot {
				separator(o, out)
			}
			prevRoot = g.rootName
			printGroupLines(o, out, g)
		}
		fmt.Fprintln(out, "```")
		fmt.Fprintln(out, "")
	}
}

func render(s *summary, o *options) {
	rows := buildRows(s, o)
	if o.format == "markdown" {
		printMarkdownPkgSections(s, o, os.Stdout)
		printMarkdownFailSections(s, o, os.Stdout)
		printPkgTable(s, o, rows, os.Stdout)
		return
	}
	if t := testTable(s, o); t != nil {
		t.print(o, os.Stdout)
	}
	printFailDetails(s, o, os.Stdout)
	pkgTable(s, o, rows).print(o, os.Stdout)
}
